-- Feature 23: append-only local synthetic contestation fixture; no product authority.
CREATE TABLE IF NOT EXISTS customer_contestation_scopes(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash),UNIQUE(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_submissions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_cases(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_lifecycle_events(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,sequence integer NOT NULL CHECK(sequence>0),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,sequence),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_findings(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_responses(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_corrections(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_remedy_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_policies(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_principals(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_feature20_contexts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_evidence_refs(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_investigations(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_actions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_deadlines(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_appeals(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_appeal_decisions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_remedy_proposals(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_authorizations(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_closures(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_root_manifests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_state_snapshots(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_test_center_bundles(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES customer_contestation_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS customer_contestation_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS customer_contestation_conflicts(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE OR REPLACE FUNCTION customer_contestation_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'customer_contestation_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customer_contestation_scopes','customer_contestation_submissions','customer_contestation_cases','customer_contestation_lifecycle_events','customer_contestation_findings','customer_contestation_responses','customer_contestation_corrections','customer_contestation_remedy_receipts','customer_contestation_policies','customer_contestation_principals','customer_contestation_feature20_contexts','customer_contestation_evidence_refs','customer_contestation_investigations','customer_contestation_actions','customer_contestation_deadlines','customer_contestation_appeals','customer_contestation_appeal_decisions','customer_contestation_remedy_proposals','customer_contestation_authorizations','customer_contestation_closures','customer_contestation_root_manifests','customer_contestation_state_snapshots','customer_contestation_test_center_bundles','customer_contestation_request_claims','customer_contestation_conflicts'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS customer_contestation_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER customer_contestation_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION customer_contestation_append_only()',t); END LOOP; END $$;
CREATE OR REPLACE VIEW customer_contestation_current_fixture_projection AS SELECT operator_test_id,scope_hash,count(*) AS case_count FROM customer_contestation_cases GROUP BY operator_test_id,scope_hash;
